INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6908673, 1041630, 83313, '<td valign="top">Nice perspective, but the badly tilted horizon hurts it for me. Sorry.</td>', 'Nice perspective, but the badly tilted horizon hurts it for me. Sorry.', '2012-11-19 00:12:49.000000', NULL, 1),
(6908674, 1041575, 15711, '<td valign="top">I like the subtlety of the mountain and the blatant shape juxtaposed.  Well done.</td>', 'I like the subtlety of the mountain and the blatant shape juxtaposed.  Well done.', '2012-11-19 00:14:33.000000', NULL, 1),
(6908678, 1041614, 15711, '<td valign="top">I love this.</td>', 'I love this.', '2012-11-19 00:15:08.000000', NULL, 1),
(6908690, 1041715, 100975, '<td valign="top">Great idea, but the tape pulls my attention away from the rest of the photo.  If you maybe could have used a solvent to melt the straws or something that would have been really cool.</td>', 'Great idea, but the tape pulls my attention away from the rest of the photo.  If you maybe could have used a solvent to melt the straws or something that would have been really cool.', '2012-11-19 00:19:54.000000', NULL, 1),
(6908691, 1041667, 114285, '<td valign="top">wHOha!!!</td>', 'wHOha!!!', '2012-11-19 00:20:55.000000', NULL, 1),
(6908692, 1041560, 100975, '<td valign="top">I really like this.</td>', 'I really like this.', '2012-11-19 00:21:05.000000', NULL, 1),
(6908694, 1041666, 100975, '<td valign="top">I like the colors.  Maybe a different angle where it would just be the ferris wheel and the sky?  The problem for me is that it feels like I am leaning to the left when I look at the picture.</td>', 'I like the colors.  Maybe a different angle where it would just be the ferris wheel and the sky?  The problem for me is that it feels like I am leaning to the left when I look at the picture.', '2012-11-19 00:23:49.000000', NULL, 1),
(6908699, 1041575, 100975, '<td valign="top">Maybe a little crop to get rid of the tree branch barely poking in on the right side.  A little more sky and a little less foreground.</td>', 'Maybe a little crop to get rid of the tree branch barely poking in on the right side.  A little more sky and a little less foreground.', '2012-11-19 00:28:51.000000', NULL, 1),
(6908702, 1041357, 100975, '<td valign="top">I would have liked to have seen more color and less gold.</td>', 'I would have liked to have seen more color and less gold.', '2012-11-19 00:30:42.000000', NULL, 1),
(6908703, 1041487, 100975, '<td valign="top">I like this.</td>', 'I like this.', '2012-11-19 00:31:12.000000', NULL, 1),
