(6908710, 1041319, 100975, '<td valign="top">The balls seem to be to high in the picture.  Maybe centered would have been better?</td>', 'The balls seem to be to high in the picture.  Maybe centered would have been better?', '2012-11-19 00:38:44.000000', NULL, 1),
