(6908720, 1041743, 100975, '<td valign="top">Maybe a different angle for the plate and pie?</td>', 'Maybe a different angle for the plate and pie?', '2012-11-19 00:43:23.000000', NULL, 1),
(6908728, 1041741, 100975, '<td valign="top">I wish I could see moreof the photo.  It is really dark.</td>', 'I wish I could see moreof the photo.  It is really dark.', '2012-11-19 00:49:12.000000', NULL, 1),
(6908729, 1041631, 100975, '<td valign="top">Really cool shot.</td>', 'Really cool shot.', '2012-11-19 00:50:40.000000', NULL, 1),
(6908731, 1041580, 100975, '<td valign="top">I think this would have looked really cool if the tri-ominoes were on a black sheet or something.  The wood grain is a real distractor for me.</td>', 'I think this would have looked really cool if the tri-ominoes were on a black sheet or something.  The wood grain is a real distractor for me.', '2012-11-19 00:52:18.000000', NULL, 1),
(6908738, 1041618, 100975, '<td valign="top">Maybe not possible to get the effect you wanted, but those would have been really great with just the sky in the background.</td>', 'Maybe not possible to get the effect you wanted, but those would have been really great with just the sky in the background.', '2012-11-19 00:59:27.000000', NULL, 1),
(6908740, 1041689, 100975, '<td valign="top">If the peak of the roof were up just a little more and shifted a little to the right in your composition, you would have cut your sky into two triangles as well.</td>', 'If the peak of the roof were up just a little more and shifted a little to the right in your composition, you would have cut your sky into two triangles as well.', '2012-11-19 01:00:56.000000', NULL, 1),
(6908748, 1041551, 100975, '<td valign="top">Seems like the lighting is off to me.  I know the point of interest is well...the point of interest, but there were some details in this photo that could have been more pronounced.  For instance, the details in the hat (since it is covering the point of interest).  Maybe you would want to draw the eyes in a little more. Smaller hat to give more of a triangular effect?  It is hard to see the fishnet for what it is.  Not that you would want giant panties, but the bra on the feet seems a little off to me.</td>', 'Seems like the lighting is off to me.  I know the point of interest is well...the point of interest, but there were some details in this photo that could have been more pronounced.  For instance, the details in the hat (since it is covering the point of interest).  Maybe you would want to draw the eyes in a little more. Smaller hat to give more of a triangular effect?  It is hard to see the fishnet for what it is.  Not that you would want giant panties, but the bra on the feet seems a little off to me.', '2012-11-19 01:09:36.000000', NULL, 1),
(6908751, 1041627, 100975, '<td valign="top">I like the many layers of triangles as you look through the picture.  I would have like a little more sky and maybe less foreground to get rid of the weeds on the right.</td>', 'I like the many layers of triangles as you look through the picture.  I would have like a little more sky and maybe less foreground to get rid of the weeds on the right.', '2012-11-19 01:11:23.000000', NULL, 1),
(6908758, 1041420, 100975, '<td valign="top">Cool shot.  I would have rated it higher had you cropped it ever so slightly and split your sky into two triangles.</td>', 'Cool shot.  I would have rated it higher had you cropped it ever so slightly and split your sky into two triangles.', '2012-11-19 01:17:22.000000', NULL, 1),
(6908760, 1041661, 100975, '<td valign="top">I would have liked this a little more had the shadows made better trinagles.</td>', 'I would have liked this a little more had the shadows made better trinagles.', '2012-11-19 01:18:54.000000', NULL, 1),
(6908762, 1041647, 100975, '<td valign="top">Is that really called the blob?</td>', 'Is that really called the blob?', '2012-11-19 01:20:14.000000', NULL, 1),
