(6909032, 1041707, 43774, '<td valign="top">Very cool architecture.</td>', 'Very cool architecture.', '2012-11-19 09:42:26.000000', NULL, 1),
(6909034, 1041614, 43774, '<td valign="top">Swizzle sticks? Very neat lighting and colours.</td>', 'Swizzle sticks? Very neat lighting and colours.', '2012-11-19 09:42:55.000000', NULL, 1),
(6909036, 1041689, 43774, '<td valign="top">What a neat barn, love the weathered wood.</td>', 'What a neat barn, love the weathered wood.', '2012-11-19 09:43:39.000000', NULL, 1),
(6909037, 1041560, 43774, '<td valign="top">Gorgeous architecture - if everyone''s library looked like that you might get more people going to them.</td>', 'Gorgeous architecture - if everyone''s library looked like that you might get more people going to them.', '2012-11-19 09:44:19.000000', NULL, 1),
(6909038, 1041625, 43774, '<td valign="top">Neat glass prism but the busy background really detracts from it. This would look great on a plain white or black background. Backlight it to get rid of reflections in the glass and the backlighting will bring out all the triangles.</td>', 'Neat glass prism but the busy background really detracts from it. This would look great on a plain white or black background. Backlight it to get rid of reflections in the glass and the backlighting will bring out all the triangles.', '2012-11-19 09:45:20.000000', NULL, 1),
