(6909685, 1041665, 114225, '<td valign="top">Is this a Venser?<br/> <br/>Looks like it could use some teeth sharpening, those chompers just aren''t vicious enough.</td>', 'Is this a Venser? Looks like it could use some teeth sharpening, those chompers just aren''t vicious enough.', '2012-11-20 16:26:58.000000', NULL, 1),
(6909686, 1041391, 114225, '<td valign="top">I kind of almost see some triangles in this, if I close one eye and look sideways.</td>', 'I kind of almost see some triangles in this, if I close one eye and look sideways.', '2012-11-20 16:27:32.000000', NULL, 1),
(6909687, 1041745, 114225, '<td valign="top">Beautiful image with great colors and depth of field.</td>', 'Beautiful image with great colors and depth of field.', '2012-11-20 16:27:57.000000', NULL, 1),
(6909688, 1041625, 114225, '<td valign="top">I''m finding this image extra distracting with the red/blue color combo and all of those strands.</td>', 'I''m finding this image extra distracting with the red/blue color combo and all of those strands.', '2012-11-20 16:28:43.000000', NULL, 1),
(6909689, 1041531, 114225, '<td valign="top">This image is a good study of movement vs stationary.</td>', 'This image is a good study of movement vs stationary.', '2012-11-20 16:29:22.000000', NULL, 1),
(6909692, 1041527, 114225, '<td valign="top">This image feels like it should have perfect symmetry. But if I draw a line done the middle of the top/front beam, I find the first lamp to be to the right of the line, and the rest to be angling away to the left. Perhaps straightening the image could have helped a bit.</td>', 'This image feels like it should have perfect symmetry. But if I draw a line done the middle of the top/front beam, I find the first lamp to be to the right of the line, and the rest to be angling away to the left. Perhaps straightening the image could have helped a bit.', '2012-11-20 16:31:42.000000', NULL, 1),
(6909693, 1041236, 114225, '<td valign="top">Good use of basic shapes to tell a story.</td>', 'Good use of basic shapes to tell a story.', '2012-11-20 16:32:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6909695, 1041590, 114225, '<td valign="top">A triangle indeed, although I don''t find the image very engaging. Feels like it has a lot of potential, but the dominant color is a bland grey. Either color or more contrast could go a long way here.</td>', 'A triangle indeed, although I don''t find the image very engaging. Feels like it has a lot of potential, but the dominant color is a bland grey. Either color or more contrast could go a long way here.', '2012-11-20 16:33:02.000000', NULL, 1),
(6909697, 1041742, 114225, '<td valign="top">I like the image, and it''s interesting how the triangle does pop out because it''s the darkest part of that area of the image.</td>', 'I like the image, and it''s interesting how the triangle does pop out because it''s the darkest part of that area of the image.', '2012-11-20 16:34:14.000000', NULL, 1),
(6909722, 1041508, 153195, '<td valign="top">I would stay there! Enchanting...</td>', 'I would stay there! Enchanting...', '2012-11-20 17:48:36.000000', NULL, 1),
(6909724, 1041551, 153195, '<td valign="top">Very interesting and unique piece :-) I like it.</td>', 'Very interesting and unique piece :-) I like it.', '2012-11-20 17:51:32.000000', NULL, 1),
(6909728, 1041739, 153195, '<td valign="top">interesting concept.</td>', 'interesting concept.', '2012-11-20 17:54:31.000000', NULL, 1),
(6909734, 1041635, 96751, '<td valign="top">The tilt shift is a good idea. I also like the glow</td>', 'The tilt shift is a good idea. I also like the glow', '2012-11-20 17:57:30.000000', NULL, 1),
(6909735, 1041739, 96751, '<td valign="top">What a great idea! Not thrilled by the hair over her eye, but lovely colors and light</td>', 'What a great idea! Not thrilled by the hair over her eye, but lovely colors and light', '2012-11-20 17:58:41.000000', NULL, 1),
(6909738, 1041380, 96751, '<td valign="top">I like the metallic abstract, and the highlighted panels add a little diversity</td>', 'I like the metallic abstract, and the highlighted panels add a little diversity', '2012-11-20 18:00:44.000000', NULL, 1),
(6909742, 1041655, 96751, '<td valign="top">I love the subtlety  og this perfect triangle. What a lovely portrait and wonderful light, although I would have cropped out everything to the right of her elbow.</td>', 'I love the subtlety  og this perfect triangle. What a lovely portrait and wonderful light, although I would have cropped out everything to the right of her elbow.', '2012-11-20 18:03:18.000000', NULL, 1),
(6909743, 1041231, 96751, '<td valign="top">This is marvelous. The tones, and the caged "wild animal" :-)</td>', 'This is marvelous. The tones, and the caged "wild animal" :-)', '2012-11-20 18:04:31.000000', NULL, 1),
(6909745, 1041741, 96751, '<td valign="top">Subtle</td>', 'Subtle', '2012-11-20 18:04:42.000000', NULL, 1),
(6909746, 1041618, 96751, '<td valign="top">Marvelous undulating metal</td>', 'Marvelous undulating metal', '2012-11-20 18:05:12.000000', NULL, 1),
(6909747, 1041236, 96751, '<td valign="top">Elemental and bold. Great eye</td>', 'Elemental and bold. Great eye', '2012-11-20 18:05:46.000000', NULL, 1),
(6909749, 1041357, 96751, '<td valign="top">I love origami, and these are terrific, although they''re fighting with the overcooked texture of the floor</td>', 'I love origami, and these are terrific, although they''re fighting with the overcooked texture of the floor', '2012-11-20 18:06:43.000000', NULL, 1),
(6909750, 1041724, 96751, '<td valign="top">Like catching the last words of an overheard conversation</td>', 'Like catching the last words of an overheard conversation', '2012-11-20 18:07:19.000000', NULL, 1),
(6909754, 1041707, 96751, '<td valign="top">Very cool. Is this a place or an object? Reflection or repetition? Very elegant</td>', 'Very cool. Is this a place or an object? Reflection or repetition? Very elegant', '2012-11-20 18:09:04.000000', NULL, 1),
(6909755, 1041487, 96751, '<td valign="top">I love how these glasses seem to be dancing</td>', 'I love how these glasses seem to be dancing', '2012-11-20 18:09:36.000000', NULL, 1),
(6909756, 1041752, 96751, '<td valign="top">Nicely seen</td>', 'Nicely seen', '2012-11-20 18:09:59.000000', NULL, 1),
(6909757, 1041658, 96751, '<td valign="top">The lighting is really great. Backlit steam and smoke always look good</td>', 'The lighting is really great. Backlit steam and smoke always look good', '2012-11-20 18:10:45.000000', NULL, 1),
(6909758, 1041471, 96751, '<td valign="top">Ha! Fabulous dof choice</td>', 'Ha! Fabulous dof choice', '2012-11-20 18:11:10.000000', NULL, 1),
(6909759, 1041496, 96751, '<td valign="top">Patterns are always so photogenic. Perfect time of day, too</td>', 'Patterns are always so photogenic. Perfect time of day, too', '2012-11-20 18:12:02.000000', NULL, 1),
(6909761, 1041676, 96751, '<td valign="top">Cheers!</td>', 'Cheers!', '2012-11-20 18:12:28.000000', NULL, 1),
(6909762, 1041631, 96751, '<td valign="top">My first reaction was to freak out because I thought it was a spider.</td>', 'My first reaction was to freak out because I thought it was a spider.', '2012-11-20 18:13:09.000000', NULL, 1),
(6909769, 1041627, 96751, '<td valign="top">That is one isolated church.....</td>', 'That is one isolated church.....', '2012-11-20 18:16:52.000000', NULL, 1),
(6909770, 1041079, 96751, '<td valign="top">Powerful leading lines with a reward at the end.</td>', 'Powerful leading lines with a reward at the end.', '2012-11-20 18:17:21.000000', NULL, 1),
(6909773, 1041749, 96751, '<td valign="top">A mystery, a glowing path, a maze, a cryptic formula or a landing strip for moonbeams</td>', 'A mystery, a glowing path, a maze, a cryptic formula or a landing strip for moonbeams', '2012-11-20 18:18:32.000000', NULL, 1),
(6909774, 1041079, 152252, '<td valign="top">One of my favorite. I love the way the triangle leads my eyes straight to the beach (the contrast between white steps and the triangle helped that a lot). I think b&amp;w was a great  idea for this one. 10</td>', 'One of my favorite. I love the way the triangle leads my eyes straight to the beach (the contrast between white steps and the triangle helped that a lot). I think b&w was a great  idea for this one. 10', '2012-11-20 18:18:34.000000', NULL, 1),
(6909776, 1041726, 96751, '<td valign="top">Truly grotesque and fascinating</td>', 'Truly grotesque and fascinating', '2012-11-20 18:19:05.000000', NULL, 1),
(6909779, 1041727, 96751, '<td valign="top">Colorful! Although the crop seems off. Maybe not so much post...?</td>', 'Colorful! Although the crop seems off. Maybe not so much post...?', '2012-11-20 18:20:05.000000', NULL, 1),
(6909780, 1041742, 96751, '<td valign="top">When the dust settled... such a historic-looking image</td>', 'When the dust settled... such a historic-looking image', '2012-11-20 18:20:56.000000', NULL, 1),
(6909781, 1041687, 96751, '<td valign="top">A popular concept, and nice light, although the colors seem a bit washed out</td>', 'A popular concept, and nice light, although the colors seem a bit washed out', '2012-11-20 18:21:54.000000', NULL, 1),
(6909783, 1041661, 96751, '<td valign="top">My favorite kind of triangle</td>', 'My favorite kind of triangle', '2012-11-20 18:22:10.000000', NULL, 1),
