(6909786, 1041743, 152252, '<td valign="top">Made me crave pumpkin pie. Would have been great for comfort foods as well. Very good light and nicely presented. (Would write more but gotta go get some pumpkin pie :)</td>', 'Made me crave pumpkin pie. Would have been great for comfort foods as well. Very good light and nicely presented. (Would write more but gotta go get some pumpkin pie :)', '2012-11-20 18:23:06.000000', NULL, 1),
(6909787, 1041667, 96751, '<td valign="top">This just made me stop and contemplate.</td>', 'This just made me stop and contemplate.', '2012-11-20 18:23:50.000000', NULL, 1),
(6909867, 1041722, 23484, '<td valign="top">This is really cool.</td>', 'This is really cool.', '2012-11-20 20:04:13.000000', NULL, 1),
(6909870, 1041658, 23484, '<td valign="top">So that''s what they call it.</td>', 'So that''s what they call it.', '2012-11-20 20:04:45.000000', NULL, 1),
(6909871, 1041676, 23484, '<td valign="top">The correct triangle.</td>', 'The correct triangle.', '2012-11-20 20:05:03.000000', NULL, 1),
(6909873, 1041751, 23484, '<td valign="top">Beautiful shot and great color.</td>', 'Beautiful shot and great color.', '2012-11-20 20:05:25.000000', NULL, 1),
(6909875, 1041707, 23484, '<td valign="top">That is really neat.</td>', 'That is really neat.', '2012-11-20 20:05:45.000000', NULL, 1),
