(6910076, 1041742, 114285, '<td valign="top">I love the tones and the mist, already voted!</td>', 'I love the tones and the mist, already voted!', '2012-11-20 23:54:29.000000', NULL, 1),
(6910077, 1041236, 114285, '<td valign="top">clever shot.</td>', 'clever shot.', '2012-11-20 23:54:47.000000', NULL, 1),
(6910645, 1041752, 149281, '<td valign="top">Very nice.</td>', 'Very nice.', '2012-11-21 11:25:04.000000', NULL, 1),
(6910650, 1041676, 149281, '<td valign="top">I got in the cupboard and opened a jar of olives. Nice</td>', 'I got in the cupboard and opened a jar of olives. Nice', '2012-11-21 11:33:24.000000', NULL, 1),
(6910688, 1041487, 112539, '<td valign="top">This type of photo is sooooo overused. Even thought it is a very good image I have seen the same type of glasses filled with colored water arranged for theme after theme. I think part of the challenge is to be original therefore I couldn''t give you the highest points.</td>', 'This type of photo is sooooo overused. Even thought it is a very good image I have seen the same type of glasses filled with colored water arranged for theme after theme. I think part of the challenge is to be original therefore I couldn''t give you the highest points.', '2012-11-21 12:17:50.000000', NULL, 1),
(6910730, 1041496, 81042, '<td valign="top">Beautiful picture. Have you tried it in B&amp;W. I think it would look awesome.</td>', 'Beautiful picture. Have you tried it in B&W. I think it would look awesome.', '2012-11-21 13:09:53.000000', NULL, 1),
(6910741, 1041680, 81042, '<td valign="top">Great contrast. Stretch on the fit but what the heck I shoe horn a pic every so often. Good job. 7</td>', 'Great contrast. Stretch on the fit but what the heck I shoe horn a pic every so often. Good job. 7', '2012-11-21 13:20:54.000000', NULL, 1),
(6910818, 1041496, 46918, '<td valign="top">I like thow shutter effect on the water. Nice light too</td>', 'I like thow shutter effect on the water. Nice light too', '2012-11-21 15:42:29.000000', NULL, 1),
(6910819, 1041689, 46918, '<td valign="top">The tree in the foreground doesn''t look quite right. Maybe it is oversaturated</td>', 'The tree in the foreground doesn''t look quite right. Maybe it is oversaturated', '2012-11-21 15:44:23.000000', NULL, 1),
(6911024, 1041627, 23484, '<td valign="top">Great stark contrast.</td>', 'Great stark contrast.', '2012-11-21 21:42:50.000000', NULL, 1),
(6911026, 1041749, 23484, '<td valign="top">Beautiful image.</td>', 'Beautiful image.', '2012-11-21 21:44:16.000000', NULL, 1),
(6911029, 1041231, 23484, '<td valign="top">The child in the image really makes this. Nice job.</td>', 'The child in the image really makes this. Nice job.', '2012-11-21 21:45:07.000000', NULL, 1),
(6911030, 1041743, 23484, '<td valign="top">I''m ready for turkey day.</td>', 'I''m ready for turkey day.', '2012-11-21 21:45:46.000000', NULL, 1),
(6911095, 1041715, 69034, '<td valign="top">I like the geometry and background, but frankly the tape is a real eye-stopper.  Excellent concept.</td>', 'I like the geometry and background, but frankly the tape is a real eye-stopper.  Excellent concept.', '2012-11-21 23:13:59.000000', NULL, 1),
(6911096, 1041739, 69034, '<td valign="top">Like the idea and composition, though with these kind of shots the line drawing might have been done better.  Still very worthy effort.</td>', 'Like the idea and composition, though with these kind of shots the line drawing might have been done better.  Still very worthy effort.', '2012-11-21 23:15:11.000000', NULL, 1),
(6911098, 1041398, 69034, '<td valign="top">I get the concept, but it might have been improved IMHO if the peppers were lit better than the background.</td>', 'I get the concept, but it might have been improved IMHO if the peppers were lit better than the background.', '2012-11-21 23:15:48.000000', NULL, 1),
(6911100, 1041580, 69034, '<td valign="top">Excellent adherence to the challenge subject.</td>', 'Excellent adherence to the challenge subject.', '2012-11-21 23:16:32.000000', NULL, 1),
(6911102, 1041631, 69034, '<td valign="top">Excellent idea, and well thought out.  It makes me think of a spider just a bit as well.</td>', 'Excellent idea, and well thought out.  It makes me think of a spider just a bit as well.', '2012-11-21 23:17:09.000000', NULL, 1),
(6911103, 1041500, 69034, '<td valign="top">Nice work with the arm.  The only drawback tends to be the sharpness is not where I would like.  Otherwise, well done.</td>', 'Nice work with the arm.  The only drawback tends to be the sharpness is not where I would like.  Otherwise, well done.', '2012-11-21 23:18:02.000000', NULL, 1),
(6911104, 1041508, 69034, '<td valign="top">Nice Subject Matter.</td>', 'Nice Subject Matter.', '2012-11-21 23:18:19.000000', NULL, 1),
(6911105, 1041667, 69034, '<td valign="top">I could be a complete moron, but I do not see the triangle here.  Still I love the composition and the noise in the shot is a great asset.</td>', 'I could be a complete moron, but I do not see the triangle here.  Still I love the composition and the noise in the shot is a great asset.', '2012-11-21 23:19:16.000000', NULL, 1),
(6911106, 1041590, 69034, '<td valign="top">Excellent use of negative space, and a well found subject.</td>', 'Excellent use of negative space, and a well found subject.', '2012-11-21 23:19:36.000000', NULL, 1),
(6911108, 1041687, 69034, '<td valign="top">Enjoy the colors.  Have seen the idea done too many times over the years to be happy with it when I can see the paper folds and cuts.  Still a worthy attempt.</td>', 'Enjoy the colors.  Have seen the idea done too many times over the years to be happy with it when I can see the paper folds and cuts.  Still a worthy attempt.', '2012-11-21 23:20:36.000000', NULL, 1),
(6911109, 1041643, 69034, '<td valign="top">Love the use of contrast as well as the triangle of negative space on the left hand side.</td>', 'Love the use of contrast as well as the triangle of negative space on the left hand side.', '2012-11-21 23:20:58.000000', NULL, 1),
(6911110, 1041471, 69034, '<td valign="top">Cute kid, excellent adherence to the subject matter.</td>', 'Cute kid, excellent adherence to the subject matter.', '2012-11-21 23:21:12.000000', NULL, 1),
(6911111, 1041740, 69034, '<td valign="top">Great job finding this triangle.  I love the organic shots like this.</td>', 'Great job finding this triangle.  I love the organic shots like this.', '2012-11-21 23:21:37.000000', NULL, 1),
(6911113, 1041572, 69034, '<td valign="top">I like the find for this shot, but it seems a bit cluttered. I can tell the processing was a bit heavy, and that kind of detracts as well.</td>', 'I like the find for this shot, but it seems a bit cluttered. I can tell the processing was a bit heavy, and that kind of detracts as well.', '2012-11-21 23:23:02.000000', NULL, 1),
(6911114, 1041674, 69034, '<td valign="top">Excellent subject and color choice.</td>', 'Excellent subject and color choice.', '2012-11-21 23:23:19.000000', NULL, 1),
(6911115, 1041509, 69034, '<td valign="top">Fantastic.  Really love this shot.  Especially with the reflection showing a square building/</td>', 'Fantastic.  Really love this shot.  Especially with the reflection showing a square building/', '2012-11-21 23:23:53.000000', NULL, 1),
(6911116, 1041689, 69034, '<td valign="top">Well done, however your processing (I assume you are using a drama filter from TOPAZ or using the Shadow/Highlight bars in PS--or equivalent program) has caused the unfortunate issues of halo.  Used to happen to me quite a bit. . .but when the sky is plain and flat, sometimes you just have to leave it.  Sigh.  ; )  Otherwise good shot.</td>', 'Well done, however your processing (I assume you are using a drama filter from TOPAZ or using the Shadow/Highlight bars in PS--or equivalent program) has caused the unfortunate issues of halo.  Used to happen to me quite a bit. . .but when the sky is plain and flat, sometimes you just have to leave it.  Sigh.  ; )  Otherwise good shot.', '2012-11-21 23:25:35.000000', NULL, 1),
(6911117, 1041647, 69034, '<td valign="top">Selective Desat done well?  Can this be.  Apparently.  Excellent shot.</td>', 'Selective Desat done well?  Can this be.  Apparently.  Excellent shot.', '2012-11-21 23:25:58.000000', NULL, 1),
(6911118, 1041079, 69034, '<td valign="top">Sneaky Sneaky.  I wonder how many people have missed the triangles of grass. . .or maybe I am giving myself too much credit for perception.  In any case I really love the B/W job you''ve this shot.</td>', 'Sneaky Sneaky.  I wonder how many people have missed the triangles of grass. . .or maybe I am giving myself too much credit for perception.  In any case I really love the B/W job you''ve this shot.', '2012-11-21 23:26:51.000000', NULL, 1),
(6911119, 1041420, 69034, '<td valign="top">This is an amazing photo.  I would love to give it a 9.  Unfortunately the noise and pixelation in the sky really distract me.  Even so 7.</td>', 'This is an amazing photo.  I would love to give it a 9.  Unfortunately the noise and pixelation in the sky really distract me.  Even so 7.', '2012-11-21 23:27:45.000000', NULL, 1),
(6911121, 1041735, 69034, '<td valign="top">Well found triangles.  My only nit pick is that the circle is not centered, which is a typical part of geometry shots.  But still a phenomenal effort.</td>', 'Well found triangles.  My only nit pick is that the circle is not centered, which is a typical part of geometry shots.  But still a phenomenal effort.', '2012-11-21 23:28:42.000000', NULL, 1),
(6911122, 1041575, 69034, '<td valign="top">Enjoyable shot.  It''s nice to see a solid landscape in this challenge.  I had the same idea with the triangle sign, but couldn''t find a way to tie it in.  You did.  Bravo.</td>', 'Enjoyable shot.  It''s nice to see a solid landscape in this challenge.  I had the same idea with the triangle sign, but couldn''t find a way to tie it in.  You did.  Bravo.', '2012-11-21 23:29:22.000000', NULL, 1),
(6911123, 1041380, 69034, '<td valign="top">Love the texture and color shift of this shot.</td>', 'Love the texture and color shift of this shot.', '2012-11-21 23:29:59.000000', NULL, 1),
(6911126, 1041749, 69034, '<td valign="top">Love the contrast.</td>', 'Love the contrast.', '2012-11-21 23:30:27.000000', NULL, 1),
(6911127, 1041665, 69034, '<td valign="top">Du nah.  Du nah.  Du nah.  Good Shot.  Wish for a bit of sharpness (no pun intended), but otherwise, great.</td>', 'Du nah.  Du nah.  Du nah.  Good Shot.  Wish for a bit of sharpness (no pun intended), but otherwise, great.', '2012-11-21 23:31:11.000000', NULL, 1),
(6911128, 1041745, 69034, '<td valign="top">Beautifully done.  I really appreciate the shadow casting behind the item, gloriously geometric.</td>', 'Beautifully done.  I really appreciate the shadow casting behind the item, gloriously geometric.', '2012-11-21 23:31:50.000000', NULL, 1),
(6911130, 1041632, 69034, '<td valign="top">. . .oh yes he did.  : )   Great find, and excellent subject.  I really wish during the processing you didn''t pick up the noise in the sky that you did, but even so, well shot.</td>', '. . .oh yes he did.  : )   Great find, and excellent subject.  I really wish during the processing you didn''t pick up the noise in the sky that you did, but even so, well shot.', '2012-11-21 23:32:27.000000', NULL, 1),
(6911131, 1041454, 69034, '<td valign="top">Love the Contre Jour.  Excellent way to keep in the challenge guide without making it uber-dominant.</td>', 'Love the Contre Jour.  Excellent way to keep in the challenge guide without making it uber-dominant.', '2012-11-21 23:33:10.000000', NULL, 1),
(6911132, 1041722, 69034, '<td valign="top">Wow.  Great idea.  I am going to have to steal this idea for later uses.  Really love it.</td>', 'Wow.  Great idea.  I am going to have to steal this idea for later uses.  Really love it.', '2012-11-21 23:33:49.000000', NULL, 1),
